import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 6 The sporting spirit","description":"学习 not so much A as B 的纠正性对比，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 6 The sporting spirit","description":"学习 not so much A as B 的纠正性对比，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 not so much A as B 的纠正性对比，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 5 Youth","link":"/life/english/new-concept/book-4/unit-01/lesson-005"},"next":{"text":"第四册：流利英语 · Lesson 7 Bats","link":"/life/english/new-concept/book-4/unit-01/lesson-007"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 5 Youth","link":"/life/english/new-concept/book-4/unit-01/lesson-005"},"next":{"text":"第四册：流利英语 · Lesson 7 Bats","link":"/life/english/new-concept/book-4/unit-01/lesson-007"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-006.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-006.md"}'),s={name:"life/english/new-concept/book-4/unit-01/lesson-006.md"};function i(r,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-6-the-sporting-spirit" tabindex="-1">第四册：流利英语 · Lesson 6 The sporting spirit <a class="header-anchor" href="#第四册-流利英语-·-lesson-6-the-sporting-spirit" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 6 The sporting spirit&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>阅读竞技运动与群体情绪之间的论证，区分作者对某些比赛现象的批评与对所有体育活动的否定。练习识别对比、范围限制和反例，说明竞争在什么规则或情绪条件下可能变得敌对。输出要把观察、原因假说与价值判断分别表达。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>rivalry</td><td>/ˈraɪvəlri/</td><td>n.</td><td>竞争关系</td><td>intense rivalry</td></tr><tr><td>fairness</td><td>/ˈfeənəs/</td><td>n.</td><td>公平</td><td>a sense of fairness</td></tr><tr><td>hostility</td><td>/hɒˈstɪləti/</td><td>n.</td><td>敌意</td><td>open hostility</td></tr><tr><td>referee</td><td>/ˌrefəˈriː/</td><td>n.</td><td>裁判</td><td>respect the referee</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>play by the rules — 按规则比赛</li><li>at stake — 处于得失关头</li></ul><h2 id="语法讲解-not-so-much-a-as-b-的纠正性对比" tabindex="-1">语法讲解：not so much A as B 的纠正性对比 <a class="header-anchor" href="#语法讲解-not-so-much-a-as-b-的纠正性对比" aria-label="Permalink to &quot;语法讲解：not so much A as B 的纠正性对比&quot;">​</a></h2><p>not so much A as B 表示与其说是 A，不如说是 B，重点在 B，不等于 A 和 B 一样多。A 与 B 最好保持语法平行，可以都是名词、动名词或形容词短语。The dispute was not so much about rules as about pride. 中两个 about 短语相互对应。此结构通常降低 A 的解释权重，并不一定完全否定 A；翻译时不能机械处理成数量比较。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The argument was not so much about the score as about respect.</p></blockquote><p>这场争论与其说是关于比分，不如说是关于尊重。</p><p>about the score 与 about respect 平行；not so much…as… 将解释重点移向 respect。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要将 not so much A as B 理解成“不如 A 那么 B”；它在两个解释之间强调后者。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 not so much 后稍停，重读 respect 或 feeling ignored；读第二遍时弱读 about，保留对比焦点。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The conflict was not so much about losing as about feeling ignored. Both captains should explain the decision calmly. A clear appeal process could reduce future arguments.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为校际比赛争执写三句评论，指出主要问题并提出一个可执行改进。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先重新界定冲突，再给出具体沟通和申诉措施，不把竞争必然等同于敌意。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例主要强调 score 还是 respect？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> respect</p><p><strong>解析：</strong> as 后的解释是重点。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>补全平行结构：not so much winning as ___ fairly（compete）。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> competing</p><p><strong>解析：</strong> winning 和 competing 都是动名词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“这与其说是速度问题，不如说是协调问题”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> It is not so much about speed as about coordination.</p><p><strong>解析：</strong> 两个 about 短语保持平行。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：not so much A as B 的纠正性对比。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-005">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-007">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(s,[["render",i]]);export{u as __pageData,b as default};
